INSERT INTO temp_seed_reviews_2000 VALUES
('54500700-0000-4000-9000-000000000501', '54500700-0000-4000-8000-000000000108', 'p-tourapi-3040204', '함파우소리체험관', '낮 12시~2시는 햇빛이 꽤 강하니까 양산이나 모자 챙기세요. 해 질 녘 골목에 가로등 켜질 때가 진짜 낭만임.', '북적', 2, '["방문팁", "산책", "솔직후기", "온마루"]'::jsonb, 35.398096, 127.384307, '2026-10-15T20:25:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000502', '54500700-0000-4000-8000-000000000142', 'p-tourapi-2707242', '위연재', '위연재 산책 겸 방문했습니다. 부모님 모시고 효도 관광으로 다녀왔는데 두 분 다 너무 좋아하셔서 뿌듯했습니다. 나무 기둥 결 하나하나 멋스러워요.', '한적', 1, '["부모님과", "가족여행", "역사체험", "고택", "온마루"]'::jsonb, 35.836188, 129.218017, '2026-10-15T20:12:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000503', '54500700-0000-4000-8000-000000000175', 'p-tourapi-2708322', '이화고택', '친구들이랑 한복 대여해서 갔는데 골목길 채광이 사기예요 ㅋㅋㅋ 사람 많아도 사진은 다 건졌음!', '북적', 1, '["사진맛집", "인생샷", "데이트", "주말나들이", "전라한옥"]'::jsonb, 35.816284, 127.153995, '2026-10-15T14:35:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000504', '54500700-0000-4000-8000-000000000153', 'p-tourapi-2717416', '올드타임', '도심 근처인데도 숲이랑 한옥이 같이 어우러져 있어서 주말 힐링 스팟으로 딱이네요. 가족들이랑 또 올 듯!', '한적', 1, '["가족나들이", "주말힐링", "숲속한옥"]'::jsonb, 37.000182, 127.200417, '2026-10-15T20:31:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000505', '54500700-0000-4000-8000-000000000116', 'p-tourapi-2657848', '한국트로트가요센터', '주변 한옥 카페들이랑 묶어서 하루 코스로 다녀오기 정말 좋아요. 사진 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["전통차", "산책로", "데이트", "힐링"]'::jsonb, 34.791589, 126.685354, '2026-10-15T18:06:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000506', '54500700-0000-4000-8000-000000000196', 'p-tourapi-3532743', '아늑한가 서울한옥 스테이 풀빌라 스파펜션', '서울 근교로 드라이브 겸 주말 나들이 나왔는데 공기도 맑고 한옥도 단정해서 너무 좋았습니다.', '한적', 1, '["근교드라이브", "주말나들이", "힐링", "온마루"]'::jsonb, 37.693766, 127.043939, '2026-10-15T21:46:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000507', '54500700-0000-4000-8000-000000000202', 'p-tourapi-3532711', '안스테이', '안스테이 산책 겸 방문했습니다. 생각보다 사람 많아서 놀랐는데 구석구석 포토존이 진짜 많네요. 오후 4시쯤 노을 질 때 강추!', '북적', 1, '["사진맛집", "인생샷", "데이트", "주말나들이"]'::jsonb, 37.765344, 127.392716, '2026-10-16T00:06:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000508', '54500700-0000-4000-8000-000000000198', 'p-tourapi-1972014', '삼락헌', '삼락헌 처음 가봤는데 대청마루의 넓은 개방감과 남도 한옥 특유의 따뜻한 온기가 참 인상 깊네요. 부모님도 대만족하셨어요.', '한적', 1, '["남도정취", "부모님과", "고택", "전라한옥"]'::jsonb, 35.815648, 127.152720, '2026-10-16T00:40:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000509', '54500700-0000-4000-8000-000000000134', 'p-tourapi-2696383', '한옥 201(Hanok 201)', '비 와서 갈까 말까 고민했는데 안 왔으면 후회할 뻔! 빗소리 들으면서 마루에 앉아있으니 운치 최고예요.', '한적', 1, '["비오는날", "고즈넉", "비멍", "분위기맛집"]'::jsonb, 37.580558, 126.985414, '2026-10-15T15:59:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000510', '54500700-0000-4000-8000-000000000144', 'p-tourapi-2572898', '고현당', '해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이나 디테일들이 다 다르게 보여요. 꼭 설명 들어보세요!', '한적', 1, '["부모님과", "가족여행", "역사체험", "고택", "온마루"]'::jsonb, 35.815292, 127.153725, '2026-10-15T17:23:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000511', '54500700-0000-4000-8000-000000000072', 'p-tourapi-250460', '남원몽심재', '''남원몽심재'' 다녀왔어요! 골목길 사이사이 전통 찻집이랑 공방 구경하느라 시간 가는 줄 몰랐네요. 한복 입고 사진 찍기 최고!', '북적', 1, '["한복체험", "데이트", "사진맛집"]'::jsonb, 35.337994, 127.374746, '2026-10-16T01:57:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000512', '54500700-0000-4000-8000-000000000079', 'p-tourapi-2992823', 'K-컬처 스크린(대한민국역사박물관)', '툇마루에 걸터앉아서 멍때리는데 풀벌레 소리 들리고... 이게 진짜 쉬는 거지 싶었음.', '한적', 1, '["고즈넉", "힐링", "혼자여행", "조용한", "서울한옥"]'::jsonb, 37.574134, 126.977574, '2026-10-16T00:48:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000513', '54500700-0000-4000-8000-000000000131', 'p-tourapi-2652952', '김해한옥체험관', '황리단길이나 안동 하회 쪽 고택들 구경하다 왔는데, 진짜 전통 한옥의 골격이 살아있어서 감탄 연발!', '북적', 1, '["전통한옥", "명소투어", "데이트", "온마루"]'::jsonb, 35.234037, 128.877208, '2026-10-16T00:52:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000514', '54500700-0000-4000-8000-000000000086', 'p-tourapi-3102129', '연월한옥', '바람 많은 제주에서 만난 아늑한 한옥 쉼터. 마당 잔디밭에 앉아서 귤차 한 잔 마시니 천국이 따로 없네요.', '한적', 1, '["제주힐링", "쉼터", "감성여행", "온마루"]'::jsonb, 33.317033, 126.269816, '2026-10-15T16:05:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000515', '54500700-0000-4000-8000-000000000064', 'p-tourapi-2393927', '충청남도 안전체험관', '골목길 따라 걷다가 구수한 냄새에 홀려서 전통 간식 사 먹었는데 꿀맛... 걷는 재미, 먹는 재미 다 잡을 수 있어요.', '한적', 1, '["전통차", "산책로", "데이트", "힐링"]'::jsonb, 36.821636, 127.191839, '2026-10-15T19:05:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000516', '54500700-0000-4000-8000-000000000148', 'p-tourapi-2604371', '노을한옥', '오랜만에 노을한옥 들렀는데 골목길 사이사이 전통 찻집이랑 공방 구경하느라 시간 가는 줄 몰랐네요. 한복 입고 사진 찍기 최고!', '북적', 1, '["한복체험", "데이트", "사진맛집"]'::jsonb, 34.851191, 127.523245, '2026-10-15T23:02:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000517', '54500700-0000-4000-8000-000000000187', 'p-tourapi-802358', '아산 대통령마을(농촌전통테마)', '주변 한옥 카페들이랑 묶어서 하루 코스로 다녀오기 정말 좋아요. 사진 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["전통차", "산책로", "데이트", "힐링", "충청한옥"]'::jsonb, 36.834409, 127.022921, '2026-10-16T00:21:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000518', '54500700-0000-4000-8000-000000000077', 'p-tourapi-2657838', '마차리폐광촌', '강원도 특유의 울창한 소나무 숲이랑 고택이 어우러져서 솔향기가 솔솔 납니다. 공기부터 달라요.', '한적', 1, '["솔향기", "자연속한옥", "강원여행", "온마루", "강원한옥"]'::jsonb, 37.255195, 128.456002, '2026-10-15T23:13:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000519', '54500700-0000-4000-8000-000000000060', 'p-tourapi-2544734', '한채당 한옥체험관', '바람 솔솔 부는 마루에 앉아 따뜻한 대추차 마시니까 피로가 싹 풀려요.', '한적', 1, '["전통차", "산책로", "데이트", "힐링"]'::jsonb, 36.830048, 126.161265, '2026-10-15T14:53:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000520', '54500700-0000-4000-8000-000000000185', 'p-tourapi-2708322', '이화고택', '주말이라 북적거리긴 한데 처마 밑 햇살 들어올 때 사진 찍으면 인생샷 무조건 건집니다 ㅎㅎ', '북적', 1, '["사진맛집", "인생샷", "데이트", "주말나들이"]'::jsonb, 35.816284, 127.153995, '2026-10-15T21:07:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000521', '54500700-0000-4000-8000-000000000062', 'p-tourapi-3426935', '구리문화재단', '도심 근처인데도 숲이랑 한옥이 같이 어우러져 있어서 주말 힐링 스팟으로 딱이네요. 가족들이랑 또 올 듯!', '한적', 1, '["가족나들이", "주말힐링", "숲속한옥", "온마루", "경기한옥"]'::jsonb, 37.595604, 127.129868, '2026-10-16T00:26:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000522', '54500700-0000-4000-8000-000000000090', 'p-tourapi-3021290', '자작자작협동조합', 'SNS에서 보고 자작자작협동조합 찾아왔는데 역광 피해서 마당 쪽 감나무 밑에서 찍어보세요. 분위기 진짜 예쁘게 잘 나옵니다.', '북적', 1, '["사진맛집", "인생샷", "데이트", "주말나들이", "충청한옥"]'::jsonb, 36.969041, 127.932752, '2026-10-16T02:10:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000523', '54500700-0000-4000-8000-000000000083', 'p-tourapi-2767851', '송도 한옥마을', 'SNS에서 보고 송도 한옥마을 찾아왔는데 부모님 모시고 효도 관광으로 다녀왔는데 두 분 다 너무 좋아하셔서 뿌듯했습니다. 나무 기둥 결 하나하나 멋스러워요.', '한적', 1, '["부모님과", "가족여행", "역사체험", "고택", "온마루", "경기한옥"]'::jsonb, 37.390252, 126.638790, '2026-10-15T14:47:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000524', '54500700-0000-4000-8000-000000000080', 'p-tourapi-2638488', '거제 관광모노레일', '''거제 관광모노레일'' 다녀왔어요! 마침 비가 부슬부슬 내리는 날 갔는데 처마에서 빗방울 떨어지는 소리가 예술입니다... 비멍 때리다 시간 다 감.', '한적', 1, '["비오는날", "고즈넉", "비멍", "분위기맛집"]'::jsonb, 34.876418, 128.625395, '2026-10-16T00:00:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000525', '54500700-0000-4000-8000-000000000118', 'p-tourapi-2600221', '박정우가옥', '박정우가옥 산책 겸 방문했습니다. 역광 피해서 마당 쪽 감나무 밑에서 찍어보세요. 분위기 진짜 예쁘게 잘 나옵니다.', '북적', 1, '["사진맛집", "인생샷", "데이트", "주말나들이", "온마루"]'::jsonb, 36.734650, 128.619780, '2026-10-15T20:54:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000526', '54500700-0000-4000-8000-000000000114', 'p-tourapi-2775014', '나무키움(전의양묘영농조합법인)', '충청도 특유의 여유로움과 단아한 한옥 마당이 너무 잘 어울려요. 툇마루에서 멍때리기 딱 좋은 명소!', '한적', 1, '["여유", "툇마루", "힐링", "온마루"]'::jsonb, 36.676447, 127.197876, '2026-10-16T01:45:40Z'::timestamptz),
('54500700-0000-4000-9000-000000000527', '54500700-0000-4000-8000-000000000145', 'p-tourapi-2507433', '삼해소주', '삼해소주 산책 겸 방문했습니다. 주말이라 북촌/서촌 나들이 온 분들 진짜 많네요! 그래도 골목길 골목길 구경하는 맛이 쏠쏠합니다.', '북적', 2, '["서울나들이", "데이트", "주말골목", "온마루"]'::jsonb, 37.562965, 126.913596, '2026-10-15T21:38:40Z'::timestamptz),
