('54500700-0000-4000-9000-000000000529', '54500700-0000-4000-8000-000000000190', 'p-tourapi-2509933', '울산 큰애기집', '아무 생각 없이 한 시간 동안 가만히 앉아있었는데 잡생각 싹 사라짐. 조용해서 너무 마음에 들어요.', '한적', 1, '["고즈넉", "힐링", "혼자여행", "조용한"]'::jsonb, 35.556627, 129.321719, '2026-10-15T15:42:40Z'::timestamptz),
